"const fs = require('fs');
const readline = require('readline');

async function main() {
  const fileStream = fs.createReadStream('C:\\Users\\jorda\\.gemini\\antigravity\\brain\\d50e19db-2019-4149-927b-196b859292c5\\.system_generated\\logs\\transcript.jsonl');
  const rl = readline.createInterface({
    input: fileStream,
    crlfDelay: Infinity
  });

  let index = 0;
  for await (const line of rl) {
    index++;
    if (line.includes('page.tsx') || line.includes('Camiseta Street Logo Off-White') || line.includes('logo_monograma_ouro.png')) {
      console.log(`Line ${index} matches! Length: ${line.length}`);
      // Let's write the matching line to a temp file so we can inspect it
      fs.writeFileSync(`match_${index}.json`, line, 'utf8');
    }
  }
}

main().catch(console.error);
